import path from 'node:path'
import { defineConfig } from 'vite'
import { holocron } from '@holocron.so/vite'

// Minimal docs site used only to produce dist/.holocron with deploy code-splitting.
// Notaku replaces assets/holocron-data.js and assets/holocron-page-*.js per tenant.

// Tenant MDX is generated by notaku's notion-mdx converters and only exists in
// the DB at deploy time, so Tailwind can never scan it here. Instead we scan
// the converter source files that emit the classNames (private-api.ts,
// notion-markdown-to-mdx.ts, ...) so those utilities are compiled into the
// shell CSS. Assumes notaku is a sibling checkout; override with NOTAKU_REPO.
const notakuRepo =
  process.env.NOTAKU_REPO || path.resolve(import.meta.dirname, '../../notaku')

export default defineConfig({
  clearScreen: false,
  plugins: [
    holocron({
      pagesDir: './src',
      pageCache: false,
      tailwindSources: [
        // .ts only: skips snapshots and multi-MB recordMap JSON assets
        path.join(notakuRepo, 'notion-mdx/src/**/*.ts'),
      ],
    }),
  ],
})
